function validate([height, width, bricks]) {
  if (!Number.isInteger(height) || height < 1 || height > 100) return 'height is an integer from 1 to 100.';
  if (!Number.isInteger(width) || width < 1 || width > 10) return 'width is an integer from 1 to 10.';
  if (!Array.isArray(bricks) || bricks.length < 1 || bricks.length > 10) return 'bricks needs 1 to 10 widths.';
  if (bricks.some(b => !Number.isInteger(b) || b < 1 || b > 10)) return 'Each brick width is an integer from 1 to 10.';
  if (new Set(bricks).size !== bricks.length) return 'Brick widths must be distinct.';
  return null;
}

