function buildWall(height, width, bricks) {
  const MOD = 1_000_000_007;
  const rows = [];

  function place(length, mask) {
    if (length === width) {
      rows.push(mask);
      return;
    }
    for (const brick of bricks) {
      const end = length + brick;
      if (end > width) {
        continue;
      }
      const seam = end < width ? 1 << end : 0;
      place(end, mask | seam);
    }
  }
  place(0, 0);

  const count = rows.length;
  const fits = rows.map(below => {
    const above = [];
    for (let j = 0; j < count; j++) {
      if ((below & rows[j]) === 0) {
        above.push(j);
      }
    }
    return above;
  });

  let dp = new Array(count).fill(1);
  for (let level = 1; level < height; level++) {
    const next = new Array(count).fill(0);
    for (let i = 0; i < count; i++) {
      for (const j of fits[i]) {
        next[j] = (next[j] + dp[i]) % MOD;
      }
    }
    dp = next;
  }

  let total = 0;
  for (const ways of dp) {
    total = (total + ways) % MOD;
  }
  return total;
}

