function buildWall(height, width, bricks) {
  // List every row as an array of brick widths, then try every stack of rows level by level.
  const rows = [];
  const extend = (row, length) => {
    if (length === width) { rows.push(row); return; }
    for (const b of bricks) if (length + b <= width) extend([...row, b], length + b);
  };
  extend([], 0);
  const cuts = rows.map(row => {
    const set = new Set();
    let sum = 0;
    for (let k = 0; k < row.length - 1; k++) { sum += row[k]; set.add(sum); }
    return set;
  });
  const compatible = (a, b) => [...cuts[a]].every(x => !cuts[b].has(x));
  const stack = (level, prev) => {
    if (level === height) return 1;
    let total = 0;
    for (let r = 0; r < rows.length; r++) if (prev < 0 || compatible(prev, r)) total += stack(level + 1, r);
    return total;
  };
  return stack(0, -1) % 1000000007;
}

