function generate(rand, size) {
  const small = size === 'small';
  const height = small ? 1 + Math.floor(rand() * 4) : 40 + Math.floor(rand() * 61);
  const width = small ? 1 + Math.floor(rand() * 5) : 5 + Math.floor(rand() * 6);
  const maxBrick = small ? 7 : 10;
  const values = [];
  for (let v = 1; v <= maxBrick; v++) values.push(v);
  for (let i = values.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  const length = small ? 1 + Math.floor(rand() * 4) : 2 + Math.floor(rand() * 9);
  const bricks = values.slice(0, length);
  if (!small && rand() < 0.5 && !bricks.includes(1)) bricks[0] = 1;
  return [height, width, bricks];
}
